            actions.insertAdjacentHTML('afterbegin', '<button type="button" class="btn btn-default btn-sm" data-toggle="modal" data-target="#ot-round-' + asset.id + '">登记投放轮次</button><button type="button" class="btn btn-default btn-sm" data-toggle="modal" data-target="#ot-version-' + asset.id + '">提交新版本</button>');
        });
    }
    if (!canEditTask) {
        document.querySelectorAll('[data-target="#ot-append-asset"], [data-target^="#ot-live-"], [data-target^="#ot-daily-"], [data-target^="#ot-retire-"], [data-target^="#ot-round-"], [data-target^="#ot-version-"], [data-target^="#ot-stop-round-"]').forEach(function (button) { button.remove(); });
    }
    document.querySelectorAll('[data-detail-tab]').forEach(function (button) {
        button.addEventListener('click', function () {
            var name = button.getAttribute('data-detail-tab');
            document.querySelectorAll('[data-detail-tab]').forEach(function (item) { item.classList.toggle('is-active', item === button); });
            document.querySelectorAll('[data-detail-pane]').forEach(function (item) { item.classList.toggle('is-active', item.getAttribute('data-detail-pane') === name); });
        });
    });
}());
</script>
@endpush
